import 'dart:convert';import 'dart:io';
import 'package:flutter/material.dart';import 'package:flutter_test/flutter_test.dart';
import 'package:flutter_core/application_modules.dart';
import 'package:flutter_core/shell_utilities.dart' show ShellUtilityLabels;
import 'package:flutter_core/component_catalogue/prime_component_catalogue.dart' show CatalogueLabels;
class ShortcutCache implements PreferenceCache {
 final data=<String,String>{};bool denied=false;
 @override Future<String?> read(String key)async=>data[key];
 @override Future<void> write(String key,String value)async{if(denied)throw StateError('cache');data[key]=value;}
 @override Future<void> remove(String key)async{data.remove(key);}
}
class ShortcutFixture {
 final scope=PreferenceScope('tenant','user','tenant_admin','live');
 final cache=ShortcutCache();int revision=0,reads=0;Object? document;bool lose=false;
 final writes=<Map<String,dynamic>>[],receipts=<String,Map<String,dynamic>>{};
 Map<String,dynamic> clone(Object? value)=>Map<String,dynamic>.from(jsonDecode(jsonEncode(value)) as Map);
 Map<String,dynamic> snapshot()=>{'version':1,'scope':scope.toJson(),'kind':'shortcuts','resource':'navigation','revision':revision,'document':document};
 Future<Object?> send(Map<String,dynamic> request)async{if(request['action']=='read'){reads++;return clone(snapshot());}writes.add(clone(request));final key=request['requestId'] as String;if(receipts.containsKey(key))return clone(receipts[key]);if(request['revision']!=revision)throw PreferenceFailure('revision_conflict',409,snapshot());revision++;document=request['document'];receipts[key]=clone(snapshot());if(lose){lose=false;throw const PreferenceFailure('offline');}return clone(snapshot());}
 ApplicationSettingsPort port()=>ApplicationSettingsPort(binding:PreferenceBinding(scope:scope,kind:'shortcuts',resource:'navigation',screenIds:['1','2','3']),transport:send,cache:cache,names:{'1':'Overview','2':'Schedule','3':'Activity'},labels:{'shortcuts':'Shortcuts','editShortcuts':'Edit'},defaults:['1']);
 ApplicationShortcutEditor editor()=>ApplicationShortcutEditor(port());
}
void main(){
 test('native editor owns the original port exclusively',()async{final f=ShortcutFixture(),port=f.port(),editor=ApplicationShortcutEditor(port);expect(()=>ApplicationShortcutEditor(port),throwsA(isA<WorkFailure>()));await expectLater(port.read(const WorkQuery()),throwsA(isA<WorkFailure>()));await expectLater(port.readItem('navigation'),throwsA(isA<WorkFailure>()));await editor.load();editor.dispose();final used=f.port();await used.read(const WorkQuery());expect(()=>ApplicationShortcutEditor(used),throwsA(isA<WorkFailure>()));used.dispose();});
 test('native defaults and picker do not auto save and explicit save has independent readback',()async{final f=ShortcutFixture(),editor=f.editor();await editor.load();expect(editor.current['selected'],['1']);expect(f.writes,isEmpty);expect(editor.destinations('sched').map((e)=>e.id),['2']);await editor.toggle('2');await editor.save();expect(f.revision,1);expect(f.reads,2);expect((f.document as Map)['screenIds'],['1','2']);expect(editor.current['status'],'clean');expect(RegExp(r'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$').hasMatch(f.writes.single['requestId'] as String),true);editor.dispose();});
 test('native reload restores original namespace draft without mutation',()async{final f=ShortcutFixture(),editor=f.editor();await editor.load();await editor.toggle('2');editor.dispose();expect(f.cache.data.keys.every((key)=>key.startsWith('application-modules.settings:')),true);final reload=f.editor();await reload.load();expect(reload.current['selected'],['1','2']);expect(f.writes,isEmpty);await reload.useDefaults();expect(reload.current['selected'],['1']);expect(f.writes,isEmpty);reload.dispose();});
 test('native lost acknowledgement reload retries exact original receipt',()async{final f=ShortcutFixture(),editor=f.editor();await editor.load();await editor.toggle('2');f.lose=true;await editor.save();final original=f.writes.single;editor.dispose();final reload=f.editor();await reload.load();expect(reload.current['status'],'conflict');await expectLater(reload.toggle('3'),throwsA(isA<WorkFailure>()));await reload.retryPending();expect(f.writes.last,original);expect(f.revision,1);expect(reload.current['pending'],isNull);expect(reload.current['status'],'clean');reload.dispose();});
 test('native conflict choices are explicit and keep local waits for separate save',()async{final f=ShortcutFixture(),editor=f.editor();await editor.load();await editor.toggle('2');f.revision=1;f.document={'version':1,'screenIds':['3']};await editor.load();await editor.keepLocal();expect(f.writes,isEmpty);expect(editor.current['selected'],['1','2']);await editor.save();expect(f.writes.single['revision'],1);expect(f.revision,2);await editor.toggle('3');f.revision=3;f.document={'version':1,'screenIds':['1']};await editor.load();await editor.acceptRemote();expect(editor.current['selected'],['1']);expect(f.writes.length,1);editor.dispose();});
 test('native cache failure blocks dispatch and explicit retry keeps its key',()async{final f=ShortcutFixture(),editor=f.editor();await editor.load();await editor.toggle('2');f.cache.denied=true;await editor.save();final key=(editor.current['pending'] as Map)['requestId'];expect(f.writes,isEmpty);f.cache.denied=false;await editor.retryPending();expect(f.writes.single['requestId'],key);expect(f.revision,1);editor.dispose();});
 test('native old WorkPort pending receipt opens in picker without migration',()async{final f=ShortcutFixture(),port=f.port();await port.read(const WorkQuery());f.lose=true;await expectLater(port.mutate(WorkCommand('navigation',1,'edit',{'body':'Schedule'}),'12345678-1234-4234-8234-123456789012'),throwsA(isA<WorkFailure>()));port.dispose();final editor=f.editor();await editor.load();expect((editor.current['pending'] as Map)['requestId'],'12345678-1234-4234-8234-123456789012');await editor.retryPending();expect(f.revision,1);expect((f.document as Map)['screenIds'],['2']);editor.dispose();});
 testWidgets('native registered recovery is explicit and keeps corrupt cache backup',(tester)async{await tester.binding.setSurfaceSize(const Size(1400,2000));addTearDown(()=>tester.binding.setSurfaceSize(null));final f=ShortcutFixture(),editor=f.editor();f.cache.data['application-modules.settings:'+editor.binding.key]='{bad';await editor.load();final shell=jsonDecode(File('../primecare_ui/catalogs/shell-utilities.registration.json').readAsStringSync()) as Map,recovery=jsonDecode(File('../primecare_ui/catalogs/application-recovery.registration.json').readAsStringSync()),labels=ShellUtilityLabels(Map<String,String>.from((shell['locales'] as Map)['en'] as Map),{for(final c in shell['controls'] as List)(c as Map)['key'] as String:c['testId'] as String});final recoveryLabels=CatalogueLabels.fromMetadata(recovery,'en');await tester.pumpWidget(MaterialApp(home:Scaffold(body:SingleChildScrollView(child:PrimeApplicationShortcuts(editor:editor,labels:labels,recoveryLabels:recoveryLabels)))));await tester.pumpAndSettle();expect(find.widgetWithText(TextButton,recoveryLabels.text('review')),findsOneWidget);expect(find.widgetWithText(TextButton,recoveryLabels.text('reset')),findsNothing);expect(f.writes,isEmpty);await tester.tap(find.widgetWithText(TextButton,recoveryLabels.text('review')));await tester.pumpAndSettle();expect(find.text(recoveryLabels.text('pendingNotice')),findsOneWidget);expect(f.writes,isEmpty);await tester.tap(find.widgetWithText(TextButton,recoveryLabels.text('reset')));await tester.pumpAndSettle();expect(f.writes.single['action'],'reset');expect(f.cache.data.keys.where((key)=>key.contains('.quarantine.')).length,1);final archive=jsonDecode(f.cache.data.entries.firstWhere((e)=>e.key.contains('.quarantine.')).value) as Map;expect(archive['raw'],'{bad');expect(tester.takeException(),isNull);await tester.pumpWidget(const SizedBox());editor.dispose();});
 final metadata=jsonDecode(File('../primecare_ui/catalogs/shell-utilities.registration.json').readAsStringSync()) as Map;
 for(final locale in ['en','fr','es']){testWidgets('native $locale picker uses registered controls and does not auto save',(tester)async{await tester.binding.setSurfaceSize(const Size(1200,1200));addTearDown(()=>tester.binding.setSurfaceSize(null));final raw=Map<String,String>.from((metadata['locales'] as Map)[locale] as Map),ids={for(final c in metadata['controls'] as List)(c as Map)['key'] as String:c['testId'] as String},labels=ShellUtilityLabels(raw,ids),fixture=ShortcutFixture(),editor=fixture.editor();await editor.load();await tester.pumpWidget(MaterialApp(home:Scaffold(body:SingleChildScrollView(child:PrimeApplicationShortcuts(editor:editor,labels:labels)))));await tester.pumpAndSettle();expect(fixture.writes,isEmpty);await tester.tap(find.widgetWithText(TextButton,'Schedule'));await tester.pumpAndSettle();expect(editor.current['selected'],['1','2']);await tester.tap(find.widgetWithText(TextButton,labels('save')));await tester.pumpAndSettle();expect(fixture.revision,1);await tester.enterText(find.byType(TextField),'sched');await tester.pumpAndSettle();expect(find.widgetWithText(TextButton,'Overview'),findsNothing);expect(find.widgetWithText(TextButton,'Schedule'),findsOneWidget);expect(tester.takeException(),isNull);await tester.pumpWidget(const SizedBox());editor.dispose();});}
}
